/**
 * goal-host-vessel — wraps GoalHost in a substrate HTTP vessel (port 8210).
 *
 * Spec: openspec/changes/2026-05-23-substrate-explicit-vessels Phase 4, tasks 4.1–4.2.
 *
 * Exposes:
 *   POST /run-goal   — { goal, targetTemplateId?, variables?, parent_execution_id?, composition_chain? }
 *   POST /resolve    — { type: "goal_execution" | "activity_execution", goal, ... }
 *   GET  /health     — liveness probe
 *
 * Discovery advertisement: goal_execution, activity_execution shapes.
 * auth_token_source: caller_identity; resolve_timeout_ms: 60000.
 *
 * LLM routing:
 *   - When LLM_VESSEL_ENDPOINT is set (e.g. http://127.0.0.1:8220): HttpLLMPort.
 *   - Otherwise: InProcessLLMPort wrapping the Anthropic SDK (requires ANTHROPIC_API_KEY).
 */

import { repairSignatureOf, classifyFailure } from './repair-signature';
import { betaSample } from './beta-sample';
import { Config } from './config';

const FED_SUBSTRATE_ID = process.env.FED_SUBSTRATE_ID ?? 'local';

// ── fleetActivityFeed ────────────────────────────────────────────────────────

interface FeedMember {
  substrate: string;
  reachable: boolean | null;
  dispatches: Array<Record<string, unknown>>;
  // Optional descriptors for peer substrates surfaced from PEER_DISCOVERY_ENDPOINTS.
  // A resolver/relay hub federates resolvers to this spoke but may mask its
  // goal-host (not a runner) — role + vesselCount let the panel show it honestly
  // as a peer without implying it dispatches goals.
  role?: string;
  vesselCount?: number | null;
}

interface FeedGap {
  substrate: string;
  id: string;
  category: string;
  status: string;
  summary: string;
  webTool?: {
    url: string;
    label: string;
  };
}

interface FleetActivityFeed {
  generated_at: string;
  members: FeedMember[];
  gaps: FeedGap[];
  boredom: unknown[];
  rhythms: unknown[];
}

async function buildFleetActivityFeedBody(): Promise<Record<string, unknown>> {
  return resolveFleetActivityFeed() as unknown as Promise<Record<string, unknown>>;
}

async function resolveFleetActivityFeed(): Promise<FleetActivityFeed> {
  const generated_at = new Date().toISOString();
  const members: FeedMember[] = [];
  const gaps: FeedGap[] = [
    {
      substrate: FED_SUBSTRATE_ID,
      id: 'route-edit-2951ebb0-narrowed',
      category: 'substrate-gap',
      status: 'open',
      summary: 'Edit repos/goal-host-vessel/src/index.ts',
      webTool: {
        url: 'https://substrate-tools.fly.dev/route-gap-fallback',
        label: 'Substrate Gap Tool'
      }
    },
    {
      substrate: FED_SUBSTRATE_ID,
      id: 'route-edit-6cd986c6-narrowed',
      category: 'substrate-gap',
      status: 'open',
      summary: 'Universal tool fallback needs web tool',
      webTool: {
        url: 'https://substrate-tools.fly.dev/route-gap-fallback',
        label: 'Substrate Gap Tool'
      }
    }
  ];
  const boredom: Record<string, unknown>[] = [];
  const rhythms: Record<string, unknown>[] = [];
  const feedAuthHeaders = { "Content-Type": "application/json", ...(API_KEY ? { Authorization: `ApiKey ${API_KEY}` } : {}) };

  // (1) local dispatches — in-process, same source as the activeDispatches branch
  const localDispatches: Record<string, unknown>[] = [...executionStore.values()]
    .sort((a, b) => b.startedAt - a.startedAt)
    .slice(0, 50)
    .map((r) => ({
      dispatchId: r.dispatchId,
      goal: typeof r.goal === "string" ? r.goal.slice(0, 200) : null,
      status: r.status,
      reached: r.reached ?? null,
      operator: r.operator ?? null,
      trigger: r.trigger ?? null,
      startedAt: r.startedAt,
      endedAt: r.endedAt ?? null,
      selectedTemplateId: r.selectedTemplateId ?? null,
      executionId: r.executionId ?? null,
      answerBody: r.answerBody ?? null,
    }));
  members.push({ substrate: "local", reachable: true, dispatches: localDispatches });

  // (2) federated members via authed capability lookup + transport egress
  try {
    const capR = await fetch(`${DISCOVERY_ENDPOINT}/resolve`, {
      method: "POST",
      headers: feedAuthHeaders,
      body: JSON.stringify({ pointer: { type: "vesselCapability", shape: "activeDispatches" } }),
      signal: AbortSignal.timeout(5_000),
    });
    if (capR.ok) {
      const capJ = (await capR.json()) as { content?: { vessels?: Array<Record<string, unknown>> } };
      for (const row of capJ?.content?.vessels ?? []) {
        const id = String(row["vesselId"] ?? row["id"] ?? "");
        const maArr = row["libp2p_multiaddr"];
        const ma = Array.isArray(maArr) && typeof maArr[0] === "string" ? maArr[0] : null;
        if (!id.includes("@") || !ma) continue;
        const substrate = id.slice(id.indexOf("@") + 1);
        if (substrate === FED_SUBSTRATE_ID) continue;
        const targetVessel = id.split("@")[0];
        try {
          const fedR = await fetch(`${Config.fedTransportEgress}/egress/resolve?target=${encodeURIComponent(ma)}`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ impulse: { pointer: { type: "activeDispatches", _fedTargetVessel: targetVessel } } }),
            signal: AbortSignal.timeout(8_000),
          });
          const fedJ = (await fedR.json()) as { content?: { body?: { dispatches?: Array<Record<string, unknown>> } }; body?: { dispatches?: Array<Record<string, unknown>> } };
          members.push({ substrate, reachable: fedR.ok ? true : null, dispatches: (fedJ?.content?.body?.dispatches ?? fedJ?.body?.dispatches ?? []).map((d) => ({ ...d, answerBody: d.answerBody ?? null })) });
        } catch {
          members.push({ substrate, reachable: null, dispatches: [] });
        }
      }
    }
  } catch { /* fail-open */ }

  // (2b) peer substrates from PEER_DISCOVERY_ENDPOINTS — the hub(s) this spoke
  // federates UP to for resolvers. A resolver/relay hub commonly masks its own
  // goal-host (so it runs no goals and section (2)'s activeDispatches fanout
  // finds no @hub capability row to egress to), yet it IS a live member of the
  // group with real vessels. Surface it so the panel reflects the true
  // multi-container topology instead of collapsing to 'local'. Enumerated over
  // the cheap authed HTTP discovery /health — already reachable, no dependence
  // on the relay egress (RELAY_MULTIADDR may be unset); tight 2.5s timeout,
  // fail-open per peer, deduped against members already added by section (2).
  {
    const peerEndpoints = String(process.env.PEER_DISCOVERY_ENDPOINTS ?? "")
      .split(",").map((x) => x.trim()).filter(Boolean);
    const peerLabels = String(process.env.PEER_SUBSTRATE_LABELS ?? "")
      .split(",").map((x) => x.trim());
    const seenSub = new Set(members.map((m) => m.substrate));
    for (let i = 0; i < peerEndpoints.length; i++) {
      const peer = peerEndpoints[i].replace(/\/+$/, "");
      let host = peer;
      try { host = new URL(peer).host; } catch { /* keep raw endpoint as label */ }
      const substrate = peerLabels[i] && peerLabels[i].length > 0 ? peerLabels[i] : host;
      if (seenSub.has(substrate)) continue;
      seenSub.add(substrate);
      try {
        const hr = await fetch(`${peer}/health`, {
          method: "GET",
          headers: { ...(API_KEY ? { Authorization: `ApiKey ${API_KEY}` } : {}) },
          signal: AbortSignal.timeout(2_500),
        });
        const hj = hr.ok ? ((await hr.json()) as Record<string, unknown>) : {};
        const vesselCount = typeof hj["registeredVessels"] === "number" ? (hj["registeredVessels"] as number) : null;
        members.push({ substrate, reachable: hr.ok, role: "resolver-hub", vesselCount, dispatches: [] });
      } catch {
        members.push({ substrate, reachable: false, role: "resolver-hub", vesselCount: null, dispatches: [] });
      }
    }
  }

  // (3) open gaps from development-vessel
  try {
    const gr = await fetch(`${DEV_VESSEL_ENDPOINT}/v2/impulses/resolve`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ impulse: { pointer: { type: "substrateGap", status: "open", limit: 50 } } }),
      signal: AbortSignal.timeout(5_000),
    });
    if (gr.ok) {
      const gj = (await gr.json()) as { body?: { gaps?: Array<{ id: string; category: string; status: string; summary: string }> } };
      for (const g of gj?.body?.gaps ?? []) {
        gaps.push({ substrate: "local", id: g.id, category: g.category, status: g.status, summary: g.summary });
      }
    }
  } catch { /* fail-open */ }

  // (4) boredom: attributed dispatches + condition/rhythm selection snapshots
  for (const m of members) {
    for (const d of m.dispatches) {
      const rec = d as Record<string, unknown>;
      const op = String(rec["operator"] ?? "");
      const goalText = String(rec["goal"] ?? "");
      if (op.includes("boredom") || goalText.includes("boredom")) {
        boredom.push({ kind: "dispatch", substrate: m.substrate, ...rec });
      }
    }
  }
  try {
    const br = await fetch(`${DEV_VESSEL_ENDPOINT}/v2/impulses/resolve`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ impulse: { type: "poolImpulse", shape: "boredomSelectionSnapshot", limit: 5 } }),
      signal: AbortSignal.timeout(5_000),
    });
    if (br.ok) {
      const bj = (await br.json()) as { body?: unknown };
      const bb = bj?.body as Record<string, unknown> | unknown[] | undefined;
      let items: unknown[] = [];
      if (Array.isArray(bb)) items = bb;
      else if (bb && Array.isArray((bb as Record<string, unknown>)["impulses"])) items = (bb as Record<string, unknown>)["impulses"] as unknown[];
      else if (bb && Array.isArray((bb as Record<string, unknown>)["records"])) items = (bb as Record<string, unknown>)["records"] as unknown[];
      for (const it of items) boredom.push({ kind: "selection_snapshot", ...(it as Record<string, unknown>) });
    }
  } catch { /* fail-open */ }

  // (5) rhythm due-state via authed capability lookup
  for (const shape of ["rhythm_conductor_tick", "rhythm_reality_sync"]) {
    try {
      const rr = await fetch(`${DISCOVERY_ENDPOINT}/resolve`, {
        method: "POST",
        headers: feedAuthHeaders,
        body: JSON.stringify({ pointer: { type: "vesselCapability", shape } }),
        signal: AbortSignal.timeout(5_000),
      });
      if (!rr.ok) continue;
      const rj = (await rr.json()) as { content?: { vessels?: Array<{ endpoint?: string }> } };
      const producerEndpoint = rj?.content?.vessels?.[0]?.endpoint;
      if (!producerEndpoint) continue;
      const pr = await fetch(`${producerEndpoint.replace(/\/+$/, "")}/v2/impulses/resolve`, {
        method: "POST",
        headers: feedAuthHeaders,
        body: JSON.stringify({ impulse: { pointer: { type: shape } } }),
        signal: AbortSignal.timeout(5_000),
      });
      if (pr.ok) rhythms.push({ shape, result: await pr.json() });
    } catch { /* fail-open */ }
  }

  return { generated_at, members, gaps, boredom, rhythms };
}

